def articulations(cells):
    adj={p:[(p[0]+dr,p[1]+dc) for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)] if (p[0]+dr,p[1]+dc) in cells] for p in cells}
    tin={};low={};art=set();t=0
    def dfs(v,parent=None):
        nonlocal t
        tin[v]=low[v]=t;t+=1; child=0
        for w in adj[v]:
            if w==parent: continue
            if w in tin: low[v]=min(low[v],tin[w])
            else:
                dfs(w,v);low[v]=min(low[v],low[w]);child+=1
                if parent is not None and low[w]>=tin[v]:art.add(v)
        if parent is None and child>1:art.add(v)
    dfs(next(iter(cells)))
    return art
