len(art),sorted(art)

def cc_on(cells):
    seen=set();out=[]
    for p in cells:
        if p in seen:continue
        q=[p];seen.add(p);co=[]
        while q:
            x,y=q.pop();co.append((x,y))
            for z in [(x-1,y),(x+1,y),(x,y-1),(x,y+1)]:
